#include <windows.h>
#include <mfapi.h>
#include <mfidl.h>
#include <mfreadwrite.h>
#include <wrl/client.h>
#include <cstdio>
#include <cmath>
using Microsoft::WRL::ComPtr;
int wmain(){CoInitializeEx(nullptr,COINIT_MULTITHREADED);MFStartup(MF_VERSION);ComPtr<IMFSourceReader> reader;wchar_t path[32768]{};GetFullPathNameW(L"windows/build/recording-smoke.mp4",32768,path,nullptr);HRESULT hr=MFCreateSourceReaderFromURL(path,nullptr,&reader);if(FAILED(hr)){printf("Open failed: %08X\n",static_cast<unsigned>(hr));return 1;}ComPtr<IMFMediaType> video,audio;MFCreateMediaType(&video);video->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Video);video->SetGUID(MF_MT_SUBTYPE,MFVideoFormat_NV12);hr=reader->SetCurrentMediaType(MF_SOURCE_READER_FIRST_VIDEO_STREAM,nullptr,video.Get());if(FAILED(hr)){printf("Video decoder failed: %08X\n",static_cast<unsigned>(hr));return 2;}MFCreateMediaType(&audio);audio->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Audio);audio->SetGUID(MF_MT_SUBTYPE,MFAudioFormat_PCM);audio->SetUINT32(MF_MT_AUDIO_BITS_PER_SAMPLE,16);hr=reader->SetCurrentMediaType(MF_SOURCE_READER_FIRST_AUDIO_STREAM,nullptr,audio.Get());if(FAILED(hr)){printf("Audio decoder failed: %08X\n",static_cast<unsigned>(hr));return 3;}unsigned frames=0;double energy=0;size_t samples=0;for(unsigned i=0;i<2000;i++){DWORD stream=0,flags=0;LONGLONG time=0;ComPtr<IMFSample> sample;hr=reader->ReadSample(MF_SOURCE_READER_ANY_STREAM,0,&stream,&flags,&time,&sample);if(FAILED(hr))return 4;if(sample){ComPtr<IMFMediaType> type;reader->GetCurrentMediaType(stream,&type);GUID major{};type->GetGUID(MF_MT_MAJOR_TYPE,&major);if(major==MFMediaType_Video)frames++;else if(major==MFMediaType_Audio){ComPtr<IMFMediaBuffer> buffer;sample->ConvertToContiguousBuffer(&buffer);BYTE* bytes=nullptr;DWORD length=0;buffer->Lock(&bytes,nullptr,&length);for(DWORD j=0;j+1<length;j+=2){const double value=*reinterpret_cast<short*>(bytes+j)/32768.0;energy+=value*value;samples++;}buffer->Unlock();}}if(flags&MF_SOURCE_READERF_ENDOFSTREAM)break;}const double rms=samples?std::sqrt(energy/samples):0;printf("Decoded recording: %u video frames; audio RMS %.4f\n",frames,rms);reader.Reset();MFShutdown();CoUninitialize();return frames>10&&rms>0.01?0:5;}
